import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Remove duplicate events (same seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort events by seq (the only reliable ordering)
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Apply replay guard and filter events
    # Build a dict of target_state for quick lookup
    target_dict = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        target_dict[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Filter events: skip if order exists in target and seq <= last_seq
    filtered_events = []
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]

        if order_id in target_dict:
            if seq <= target_dict[order_id]["last_seq"]:
                # Replay guard: skip this event
                continue

        filtered_events.append(event)

    if not filtered_events:
        filtered_events = pd.DataFrame(columns=cdc_events.columns)
    else:
        filtered_events = pd.DataFrame(filtered_events)

    # Step 4: Apply events in seq order
    # Track which orders had a row (for tombstones logic)
    orders_with_row = set(target_dict.keys())

    for _, event in filtered_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        if op in ("I", "U"):
            if order_id in target_dict:
                # Update existing row
                target_dict[order_id]["status"] = status
                # For U with NULL amount, leave amount unchanged
                if op == "U" and pd.isna(amount):
                    pass  # amount stays the same
                else:
                    target_dict[order_id]["amount"] = amount
                target_dict[order_id]["last_seq"] = seq
            else:
                # Create new row
                target_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
                orders_with_row.add(order_id)

        elif op == "D":
            if order_id in target_dict:
                del target_dict[order_id]

    # Step 5: Determine tombstones
    # For each order that had a row, check if its last applied event was D
    tombstones_list = []

    for order_id in orders_with_row:
        # Find the last applied event for this order
        order_events = filtered_events[filtered_events["order_id"] == order_id]
        if len(order_events) > 0:
            last_event = order_events.iloc[-1]
            if last_event["op"] == "D":
                tombstones_list.append({
                    "order_id": order_id,
                    "deleted_seq": last_event["seq"]
                })

    # Step 6: Build output new_state from target_dict
    new_state_list = []
    for order_id, data in target_dict.items():
        new_state_list.append({
            "order_id": order_id,
            "status": data["status"],
            "amount": data["amount"],
            "last_seq": data["last_seq"]
        })

    if new_state_list:
        new_state = pd.DataFrame(new_state_list)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Ensure correct dtypes for new_state
    if len(new_state) > 0:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["status"] = new_state["status"].astype("object")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
    else:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["status"] = new_state["status"].astype("object")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")

    if tombstones_list:
        tombstones = pd.DataFrame(tombstones_list)
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
